    author: 'Raden Amar Ar-Risalah',
    imprint: 'Gensa Berilmu',
    description:
      'Men Around Aqsa; Booklet Ismail Haniyah\n\nRaden Amar Ar-Risalah\n\n \n\n     Judul : Men Around Aqsa, Booklet Ismail Haniyah\n     Penulis : Raden Amar Ar-Risalah\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 14.8 x 21 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, September 2024\n\nSinopsis : \n\nKau memang telah tiada, tapi namamu insya Allah akan abadi. Namamu tercatat sebagai salah satu komandan kaum muslimin yang bertempur melawan musuh saat semua orang takut atau bungkam.\n\nAku menulis risalah ini, 21 hari setelah engkau syahid. Setelah bukuku terlanjur terbit dan aku tak memasukkan kisah menakjubkan milikmu di sana. Bukuku, Thufan Al Aqsa, dicetak saat kau sedang dalam perjalanan dari Doha ke Teheran untuk menghadiri pelantikan Presiden Iran.\n\nAllah akan abadikan namamu menjadi nama anak-anak kaum muslimin. Aku pun telah banyak menjumpai banyak anak kaum muslimin di negeriku yang dinamai dengan namamu, atau nama para pemimpin sebelummu:\n\nAbdul Aziz Rantisi, Ahmad Yassin, sampai Izzuddin Al-Qassam.\n\nMusuh mengira dengan ketiadaanmu, perjuangan ini berhenti. Namun justru pertempuran makin memanas, dan tenaga juang semakin segar dari waktu ke waktu.\n\nKesyahidanmu menjadi bahan bakar perlawanan untuk kami!\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - 28 Halaman - 25 gram',
