      'Men Around Aqsa; Father Of Rockets Adnan Al-Ghoul\n\nRaden Amar Ar-Risalah\n\n \n\n     Judul : Men Around Agsa; Father Of Rockets Adnan Al-Ghoul\n     Penulis : Raden Amar Ar-Risalah\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 10 x 14.5 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, November 2024\n\nSinopsis : \n\nTokoh kita kali ini, Sahabat, lebih dikenal dengan nama Adnan Al-Ghoul. Saat ibunya melahirkannya, dia dinamai Yahya Al-Ghoul. Namun sang kakak, Zainab, tak mau adiknya tercinta dipanggil Yahya.\n“Adnan! Aku mau namanya Adnan!” katanya.\n\n“Baiklah!” kata sang Ibu. “Kita panggil dia Adnan, tapi di catatan sipil, kita tulis namanya Yahya!”\nHari itu di penghujung 1958, sang Ayah, Mahmud namanya, sedang mendekam di dalam penjara. Dulunya, dia adalah komandan dalam pertempuran Nakba 1948. Setelah Israel mendeklarasikan diri, terjadi penangkapan para prajurit asli Palestina.\n\nAyahnya yang dipenjara membuat kekuatan jiwa Adnan bangkit. Dia tumbuh menjadi pemuda yang menginginkan perlawanan total. Dia sangat mengerti, pertempuran yang terjadi di sekitarnya selalu tidak seimbang dan memang tidak pernah seimbang.\n“Aku harus menciptakan senjata. Aku harus memperpendek jarak kelemahan ini.” Itulah niatnya.\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - 28 Halaman - 25 gram',
