    description:
      'Men Around Aqsa; Mother Of Martyrs Ummu Nidhal\n\nRaden Amar Ar-Risalah\n\n \n\n     Judul : Men Around Aqsa; Men Around Agsa; Mother Of Martyrs Ummu Nidhal\n     Penulis : Raden Amar Ar-Risalah\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 10 x 14.5 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, November 2024\n\nSinopsis : \n\nHari itu, Sahabat, setahun setelah peristiwa Nakba. Setahun setelah kaum muslimin terusir dan menempati kamp-kamp pengungsian tahun 1949, lahirlah seorang bayi perempuan.\n\nPerempuan ini akan mengasuh para lelaki yang kelak mengubah wajah dunia selamanya. Orang tuanya memberinya nama Maryam Muhaisan. Dia tumbuh menjadi perempuan yang sangat cantik dan menyaksikan usia awal pernikahannya pada masa Perang Enam Hari.\n\nDia pun kerap mengikuti majelis yang diadakan oleh Syaikh Ahmad Yasin, yang kau sudah sangat mengenalnya. Beliau adalah satu-satunya orang yang kutahu, yang pernah mencoba membebaskan Masjidil Aqsa dari atas kursi roda.\n\nSyaikh Ahmad Yasin mendirikan sebuah gerakan yang kelak akan mengguncang Zionisme di bumi Palestina selama puluhan tahun lamanya, Harakah Muqawamah Al-Islamiyah atau kau akan lebih mengenalnya dengan nama Hamas.\n\nSahabat Syaikh Ahmad Yasin yang bernama Syaikh Shalah Shehadeh mendirikan sebuah pasukan khusus para mujahidin yang terlatih. Nama pasukan itulah yang kini begitu terlarang disebut di depan kezaliman: Brigade Izzuddin Al-Qassam.\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - 28 Halaman - 25 gram',
