    description:
      'Men Around Aqsa; Nabi-nabi dan Al-Aqsa\n\nEdgar Hamas\n\n \n\n     Judul : Men Around Agsa; Nabi-nabi dan Al-Aqsa\n     Penulis : Edgar Hamas\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 10 x 14.5 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, November 2024\n\nSinopsis : \n\nRasulullah ﷺ menekankan pentingnya jihad dan pertahanan Al Aqsa serta Palestina, menunjukkan bahwa Palestina akan selalu menjadi tempat penting dalam menjaga risalah Islam. Nabi ﷺ bersabda, “Akan ada sekelompok dari umatku yang terus berada di atas kebenaran, menang atas musuh mereka, hingga datang ketentuan Allah dan mereka tetap demikian. Beliau ditanya: ‘Di mana mereka?’ Nabi menjawab: ‘Di Baitul Maqdis dan sekitar Baitul Maqdis.’” (HR. Ahmad)\n\nAllah sering menyebut dalam ayat-ayat Al Qur’an tentang keberkahan tanah Palestina, dan kabar ini ditujukan kepada umat Rasulullah ﷺ. Berkah dari Masjid Al Aqsa meluas ke tanah di sekitarnya, menegaskan posisi Palestina sebagai tanah yang diberkahi. Allah berfirman, “Yang telah Kami berkahi sekelilingnya.” (Al Isra’ 1)\n\nPara salaf menyebutkan bahwa berkah ini mencakup kelimpahan rezeki, buah-buahan, juga keberadaan nabi-nabi yang tinggal di tanah tersebut.\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - 28 Halaman - 25 gram',
