      'Men Around Aqsa; Sahabat Nabi dan Al-Aqsa\n\nEdgar Hamas\n\n \n\n     Judul : Men Around Agsa; Sahabat Nabi dan Al-Aqsa\n     Penulis : Edgar Hamas\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 10 x 14.5 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, November 2024\n\nSinopsis : \n\nKeadilan pemerintahan dan kepemimpinan yang kuat menjadikan pembebasan Al Aqsa merupakan peristiwa penting di masanya.\n\nUmar bin Khattab dikenal karena keadilan dan ketegasan dalam menegakkan syariat Islam, yang tercermin dalam cara beliau memimpin negara Islam setelah pembebasan. Keberhasilannya dalam membebaskan Baitul Maqdis adalah hasil dari kebijaksanaan politik dan kepemimpinan militernya yang luar biasa.\n\nSetelah pembebasan Baitul Maqdis, Umar berusaha untuk memperkuat keamanan dan stabilitas di kota tersebut. Beliau menjadikannya pusat ibadah dan pendidikan, tempat para ulama mulai mengajarkan ilmu-ilmu agama. Umar juga mengeluarkan instruksi ketat untuk melindungi seluruh penduduk tanpa memandang agama mereka.\n\nKeadilan dalam pemerintahan dan kepemimpinannya yang kuat membuatnya dihormati oleh umat Islam dan non muslim di kota tersebut. Pembebasan Baitul Maqdis menjadi salah satu momen penting dalam masa kepemimpinannya sebagai khalifah. (Ibn Abdul Hakam, Futuh Misr wa Akhbaruha, hlm. 52)\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - 28 Halaman - 25 gram',
