    author: 'Edgar Hamas',
    imprint: 'Generasi Shalahuddin Berilmu',
    description:
      'Paket Booklet Serial Men Around Aqsa\n\nEgar Hamas ; Raden Amar Ar-Risalah\n\n \n\n     Judul : Paket Booklet Serial Men Around Aqsa\n     Penulis : Edgar Hamas ; Raden Amar Ar-Risalah\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n28 Halaman, Ukuran 10 x 14.5 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, November 2024\n\nSinopsis : \n\nDulu ketika kecil, aku bertanya-tanya, buat apa membela Palestina padahal kita jauh jaraknya di Indonesia.\n\n Aku bahkan pernah menghitung dan menarik garis lurus dari Palestina ke tempat tinggalku: nyaris 9000 kilometer!\n\n Jadi, kenapa aku perlu memberi perhatianku pada negeri nun jauh itu?\n\n Sampai akhirnya aku belajar sejarah orang-orang hebat, mulai dari Baginda Rasulullah ﷺ sang manusia paripurna hingga para sahabat yang mulia. Aku pun mempelajari kisah pahlawan pembebas hingga generasi Syaikh Yasin dan Rantissi.\n\n Dan aku sadar...\n\n Permasalahan Al Aqsha dan Palestina adalah masalah umat Islam sedunia, dan hanya orang-orang faqih pada Islamnya, berhati mulia dan bermental kesatria yang pasti punya perhatian pada Al Aqsha dan Palestina.\n\n Mereka, Men Around Aqsa, adalah inspirasi bagiku untuk terus bersuara. Sebab aku ingin Allah kumpulkan kelak bersama kesatria di sekitar Al Aqsha. Mulai dari Nabi Muhammad, Ibunda Maryam, Abu Ubaidah, Umar, Khalid, Shalahuddin, Baibars, Abdul Hamid II, Ummu Nidhal, hingga komandan Sinwar.\n\n Agar aku, kamu, kita semua, mengilmui jalan panjang para pahlawan, dan moga tercatat dalam satu daftar manusia-manusia hebat...\n\n Men Around Aqsha.\n\n \n\nSoft Cover - Full Colour - Full Ilustrasi - Kertas HVS - @28 Halaman - @25 gram',
