    description:
      'Judul : The Leader of Liberation, Kisah Syekh Ahmad Yasin; Pria Bersahaja di Atas Kursi Roda Penggerak Roda Pembebasan Al Aqsha\n\nPenulis : Amir Syammakh\n     —\n     Kota Depok\n     PT. Generasi Shalahuddin Berilmu\n\n220 Halaman, Ukuran 14.8 x 21 cm\n\nNomor ISBN :\n\nTema Buku : Sejarah Islam\n\nCetakan Pertama, April 2026\n\nSinopsis : \n\nMengapa mereka begitu cepat melakukan pembunuhan terhadap sang Syekh? Sementara yang lain dibiarkan tetap berada di markasnya?\n\nSebuah pertanyaan yang muncul dari rangkaian peristiwa dan dijawab oleh salah seorang analis terkemuka: Sesungguhnya, teguhnya pendirian sang Syekh menjadi simbol perlawanan yang kokoh dan keras kepala, di saat yang lain telah menjadi simbol kompromi politik.\n\nBerdirinya sang Syekh di garis terdepan adalah representasi perlawanan. Maka, pembunuhan terhadapnya—bahkan sampai pada tindakan keji terhadap jasadnya—dimaksudkan untuk membunuh seluruh nilai yang ia wakili. Artinya, roket-roket yang diarahkan kepadanya, sejatinya menargetkan kita semua. Tujuannya bukan hanya untuk merobek tubuhnya, tetapi juga untuk melemahkan tekad kita, serta menebarkan keputusasaan dan kekalahan di tengah kaum Muslimin pada umumnya, terutama rakyat Palestina pada khususnya.\n\nBuku ini merupakan upaya mengabadikan kenangan harum sang Syekh, sekaligus merekam sebagian sisi dari kehidupan yang sarat dengan jihad, tantangan, dan keteguhan. Ia adalah syekh para mujahid, yang enggan menjadi golongan orang-orang lemah yang diberi keringanan oleh Allah. Ia seakan mengisahkan kembali perjalanan Amr bin al-Jamuh yang bertekad menginjakkan kakinya yang pincang menuju surga. Syekh kita ini seluruh anggota tubuhnya lumpuh, tetapi ia kuat dalam iman dan kehendak, muda dalam hati dan tekad. Ia ingin memasuki surga dengan kursi rodanya, agar memperoleh kedudukan yang mulia di sisi Raja Yang Maha Berkuasa, insya Allah.\n\nYa Allah, masukkanlah ia ke dalam golongan para shiddiqin dan para syuhada, serta pertemukanlah kami dengannya dalam keadaan sebagai orang-orang yang saleh lagi memperbaiki, teguh tanpa berubah.\n\nSalam sejahtera atas para syuhada yang mulia dan segala puji bagi Allah, Tuhan semesta alam.\n\nSoft Cover - Full Colour - Full Ilustrasi - HVS - 220Halaman - 450 gram',
