    author: 'Redaksi',
    contentHtml:
      '<p>Palestian jatuh bukan hanya karena peluru, tapi karena narasi. Dua sosok di balik sejarah kelam ini bukanlah militer! Bukan penguasa, bukan jenderal. Satu seorang paus, satu lagi seorang jurnalis. Paus Urbanus II berpidato sekali di Clermont. Tapi pidato itu menyalakan api perang selama 200 tahun. Menggerakkan satu juta tentara dalam sembilan gelombang. Theodor Herzl menulis sebuah buku tipis tahun 1896. Banyak orang menertawakannya. Tapi 52 tahun kemudian buku itu menjelma menjadi negara. Keduanya tidak memimpin pasukan. Keduanya tidak mengangkat senjata. Mereka mengorganisir sebuah ide. Palestina jatuh dua kali dalam sejarah. Kebenaran yang tidak terorganisir akan dikalahkan. Siapa yang akan mengorganisir kebenaran?</p>',
