async function seedAdmin() {
  const passwordHash = await bcrypt.hash('admin123', 10);
  const admin = await prisma.user.upsert({
    where: { email: 'admin@gensaberilmu.co.id' },
    update: {},
    create: {
      email: 'admin@gensaberilmu.co.id',
      passwordHash,
      name: 'Admin Gensa Berilmu',
      role: 'ADMIN',
    },
  });
  return admin;
}

async function seedCategories() {
  const categoryIdBySlug = new Map<string, string>();

  for (const category of GENSA_CATEGORIES) {
    const record = await prisma.category.upsert({
      where: { slug: category.slug },
      update: { name: category.name },
      create: { slug: category.slug, name: category.name },
    });
    categoryIdBySlug.set(record.slug, record.id);
  }

  return categoryIdBySlug;
}

async function seedProducts(categoryIdBySlug: Map<string, string>, adminUserId: string) {
  const productIdBySku = new Map<string, string>();

  for (const item of GENSA_PRODUCTS) {
    const product = await prisma.product.upsert({
      where: { sku: item.sku },
      update: {},
      create: {
        sku: item.sku,
        slug: item.slug,
        title: item.title,
        subtitle: item.subtitle,
        author: item.author,
        imprint: item.imprint,
        description: item.description,
        price: item.price,
        discountPercent: item.discountPercent,
        finalPrice: item.finalPrice,
        stock: item.stock,
        weightGram: item.weightGram,
        coverType: item.coverType,
        pageCount: item.pageCount,
        publishYear: item.publishYear,
        position: item.position,
        isActive: item.isActive,
        ribbonType: item.ribbon?.type,
        ribbonText: item.ribbon?.text,
      },
    });

    for (const [position, image] of item.images.entries()) {
      const existingImage = await prisma.productImage.findFirst({
        where: { productId: product.id, url: image.url },
      });
      if (!existingImage) {
        await prisma.productImage.create({
          data: {
            productId: product.id,
            url: image.url,
            isPrimary: image.isPrimary,
            position,
          },
        });
      }
    }

    for (const categorySlug of item.categories) {
      const categoryId = categoryIdBySlug.get(categorySlug);
      if (!categoryId) continue;
      await prisma.categoryProduct.upsert({
        where: { productId_categoryId: { productId: product.id, categoryId } },
        update: {},
        create: { productId: product.id, categoryId },
      });
    }

    await prisma.affiliateCommissionRate.upsert({
      where: { productId: product.id },
      update: {},
      create: {
        productId: product.id,
        percent: 5,
        isActive: true,
        updatedByUserId: adminUserId,
      },
    });

    productIdBySku.set(item.sku, product.id);
  }

  return productIdBySku;
}

async function seedHomepageBanners() {
  for (const banner of HOMEPAGE_BANNERS) {
    const existing = await prisma.homepageBanner.findFirst({
      where: { slot: banner.slot, position: banner.position },
    });
    if (existing) {
      await prisma.homepageBanner.update({ where: { id: existing.id }, data: banner });
    } else {
      await prisma.homepageBanner.create({ data: banner });
    }
  }
}

async function seedHomepageSections(productIdBySku: Map<string, string>) {
  for (const section of HOMEPAGE_SECTIONS) {
    const record = await prisma.homepageSection.upsert({
      where: { key: section.key },
      update: {
        title: section.title,
        subtitle: section.subtitle,
        promoImageUrl: section.promoImageUrl,
        position: section.position,
        isEnabled: section.isEnabled,
        backgroundColor: section.backgroundColor,
        titleColor: section.titleColor,
      },
      create: {
        key: section.key,
        title: section.title,
        subtitle: section.subtitle,
        promoImageUrl: section.promoImageUrl,
        position: section.position,
        isEnabled: section.isEnabled,
        backgroundColor: section.backgroundColor,
        titleColor: section.titleColor,
      },
    });

    for (const [position, sku] of section.productSkus.entries()) {
      const productId = productIdBySku.get(sku);
      if (!productId) continue;
      const existingLink = await prisma.homepageSectionProduct.findFirst({
        where: { sectionId: record.id, productId },
      });
      if (!existingLink) {
        await prisma.homepageSectionProduct.create({
          data: { sectionId: record.id, productId, position },
        });
      }
    }
  }

  await prisma.homepageSection.deleteMany({
    where: { key: { notIn: HOMEPAGE_SECTIONS.map((section) => section.key) } },
  });
}

async function seedCities() {
  for (const city of CITIES) {
    const existing = await prisma.city.findFirst({ where: { name: city.name } });
    if (!existing) {
      await prisma.city.create({ data: city });
    }
  }
}

async function seedBlogPosts() {
  for (const post of BLOG_POSTS) {
    await prisma.blogPost.upsert({
      where: { slug: post.slug },
      update: {},
      create: {
        slug: post.slug,
        title: post.title,
        excerpt: post.excerpt,
        author: post.author,
        contentHtml: post.contentHtml,
        coverImageUrl: post.coverImageUrl,
        status: 'PUBLISHED',
        publishedAt: post.publishedAt,
      },
    });
  }
}

async function seedVouchers(adminUserId: string) {
  await prisma.voucher.upsert({
    where: { code: 'WELCOME10' },
    update: {},
    create: {
      code: 'WELCOME10',
      description: 'Diskon 10% untuk pembeli baru',
      type: VoucherType.PERCENT,
      value: 10,
      maxDiscount: 20000,
      channel: VoucherChannel.ALL,
      isActive: true,
      createdByUserId: adminUserId,
    },
  });

  await prisma.voucher.upsert({
    where: { code: 'POSGROSIR' },
    update: {},
    create: {
      code: 'POSGROSIR',
      description: 'Potongan Rp15.000 untuk pembelian grosir di kasir POS',
      type: VoucherType.FIXED,
      value: 15000,
      minPurchase: 100000,
      channel: VoucherChannel.POS,
      isActive: true,
      createdByUserId: adminUserId,
    },
  });
}

async function main() {
  const admin = await seedAdmin();
  const categoryIdBySlug = await seedCategories();
  const productIdBySku = await seedProducts(categoryIdBySlug, admin.id);
  await seedCities();
  await seedVouchers(admin.id);
  await seedBlogPosts();
  await seedHomepageBanners();
  await seedHomepageSections(productIdBySku);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
